-- =====================================================================
--  RAB rekonsiliasi 26/10/2026 (sekali jalan, setelah 62_proyek.sql v11)
--  Sumber: RAB Inda Sofia (Sheet1, versi benar) + pos RAB Aktual 2025 +20%
--  yang tidak ada padanannya. Baris RAB lama DIARSIPKAN (bisa dipulihkan),
--  tidak dihapus. Aman diulang: dijalankan hanya bila belum pernah.
-- =====================================================================
do $$
begin
if exists (select 1 from jo.settings where key = 'pm_rab_rekon_20261026') then
  raise notice 'Rekonsiliasi RAB 26/10/2026 sudah pernah dijalankan.'; return;
end if;

-- 1) arsipkan seluruh baris RAB lama, sembunyikan seksi lama A-Q
update jo.pm_rab_items set archived_at = now(), updated_at = now() where archived_at is null;
update jo.pm_rab_sections set hidden = true;

-- 2) seksi baru I-X + catatan efisiensi (harga final)

  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = excluded.sort, hidden = false, is_note = false;
  on conflict (code) do update set name = excluded.name, fixed_price = true, sort = 200, hidden = false, is_note = true;

-- 3) baris RAB

-- 4) parameter
update jo.pm_rab_params set event_days = 10, updated_at = now(),
  note = 'RAB rekonsiliasi 26/10/2026: RAB Inda Sofia (Sheet1) sebagai dasar, ditambah pos RAB Aktual 2025 +20% yang tidak ada padanannya. Website dihitung Rp100.000.000 (angka Inda Sofia); usulan Daffa A1+A2 Rp95.005.000 dan Instagram Rp1.200.000 tampil sebagai acuan, tidak dihitung. Jumlah hari kegiatan dipakai baris yang mengikuti hari kegiatan.'
 where id = 1;

-- 5) Gantt: pulihkan tugas 80-81 yang tidak ikut impor awal, tambah tugas 113-116, tandai 44 selesai
select v.no, 6, v.task, '[Nama]', v.role, (select id from jo.pm_divisions where name = v.div and archived_at is null), v.s::date, v.e::date, v.pred::integer[], 'Belum mulai', v.note,
       v.no * 10
  from (values
    (80, 'Banner, backdrop, spanduk: desain (logo sponsor final)', 'Div. Humas & Media', 'Humas & Media', '2026-11-23', '2026-11-30', '{30}', null, 1),
    (81, 'Banner, backdrop, spanduk: cetak', 'Div. Logistik', 'Logistik', '2026-12-01', '2026-12-08', '{80}', null, 2),
    (113, 'Kaos peserta & panitia (1.000 pcs): desain, ukuran, vendor', 'Div. Logistik', 'Logistik', '2026-11-02', '2026-11-13', '{}', 'Pos RAB IV. Ukuran dari data pendaftaran; logo sponsor final menyusul.', 3),
    (114, 'Kaos peserta & panitia: pesan, produksi & distribusi', 'Div. Logistik', 'Logistik', '2026-11-16', '2026-12-08', '{113}', 'Tambahan ukuran setelah pendaftaran ditutup 27 Nov.', 4),
    (115, 'Sewa tenda booth tenant (15 unit): vendor & kontrak', 'Div. Logistik', 'Logistik', '2026-11-09', '2026-11-20', '{}', 'Pos RAB II. Jumlah unit mengikuti denah booth (tugas 22 & 23).', 5),
    (116, 'Medali festival (111) & piala: masuk pesanan medali tahap 1', 'Div. Logistik', 'Logistik', '2026-11-10', '2026-11-10', '{}', 'Pos RAB IV. Ikut pesanan medali tahap 1.', 6)
  ) as v(no, task, role, div, s, e, pred, note, k)
 where not exists (select 1 from jo.pm_tasks t where t.no = v.no);
update jo.pm_tasks set status = 'Selesai', percent = 1, updated_at = now() where no = 44 and status <> 'Selesai';

  on conflict (key) do update set value = excluded.value, updated_at = now();
end $$;
